import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Configuration Reference — Glacier","description":"Every Glacier setting documented — key, type, default, range, what it does and when to change it.","frontmatter":{"title":"Configuration Reference — Glacier","description":"Every Glacier setting documented — key, type, default, range, what it does and when to change it."},"headers":[],"relativePath":"glacier/configuration/reference.md","filePath":"glacier/configuration/reference.md","lastUpdated":1785230800000}'),r={name:"glacier/configuration/reference.md"};function a(i,t,n,s,l,h){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="configuration-reference" tabindex="-1">Configuration Reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration Reference&quot;">​</a></h1><p>Every setting Glacier owns, grouped by the admin hub tab it lives on (<strong>Admin → Extensions → Glacier</strong>). All values are stored panel-wide and apply immediately after save; users may need one refresh.</p><p>Conventions:</p><ul><li><strong>Switch</strong> — a boolean toggle stored as <code>1</code> (on) or <code>0</code> (off).</li><li><strong>Hex</strong> — a <code>#rrggbb</code> color. The hub provides a color picker everywhere a Hex is expected.</li><li><strong>Integer ranges</strong> are inclusive; out-of-range values are rejected on save with a field hint.</li><li>Keys are listed by their internal name — the hub labels match one-to-one.</li></ul><hr><h2 id="appearance" tabindex="-1">Appearance <a class="header-anchor" href="#appearance" aria-label="Permalink to &quot;Appearance&quot;">​</a></h2><p>Mode, corner radius, both color palettes, and small identity extras.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>mode</code></td><td><code>dark</code> · <code>light</code> · <code>auto</code></td><td><code>dark</code></td><td>Panel-wide color mode. <code>auto</code> follows each visitor&#39;s OS preference.</td></tr><tr><td><code>radius</code></td><td>int 8–16</td><td><code>14</code></td><td>Corner radius (px) shared by cards, containers, inputs and buttons. Lower = squarer, higher = softer.</td></tr><tr><td><code>accent</code></td><td>Hex</td><td><code>#4ec5b1</code></td><td>Dark-mode accent: links, active states, focus rings, chips.</td></tr><tr><td><code>bg</code></td><td>Hex</td><td><code>#070707</code></td><td>Dark-mode page background.</td></tr><tr><td><code>surface</code></td><td>Hex</td><td><code>#141414</code></td><td>Dark-mode base surface (lists, tables).</td></tr><tr><td><code>elevated</code></td><td>Hex</td><td><code>#1e1e1e</code></td><td>Dark-mode raised surface (cards, popovers).</td></tr><tr><td><code>ink</code></td><td>Hex</td><td><code>#f2f2f2</code></td><td>Dark-mode primary text.</td></tr><tr><td><code>muted</code></td><td>Hex</td><td><code>#9e9e9e</code></td><td>Dark-mode secondary text and icons.</td></tr><tr><td><code>border</code></td><td>Hex</td><td><code>#2e2e2e</code></td><td>Dark-mode strong borders.</td></tr><tr><td><code>success</code></td><td>Hex</td><td><code>#59c886</code></td><td>Dark-mode success/online states.</td></tr><tr><td><code>warning</code></td><td>Hex</td><td><code>#ebbd57</code></td><td>Dark-mode warning/starting states.</td></tr><tr><td><code>danger</code></td><td>Hex</td><td><code>#f75d59</code></td><td>Dark-mode danger/offline states.</td></tr><tr><td><code>light_accent</code></td><td>Hex</td><td><code>#148d7f</code></td><td>Light-mode accent. Slightly deeper than the dark accent keeps contrast on white.</td></tr><tr><td><code>light_bg</code></td><td>Hex</td><td><code>#ffffff</code></td><td>Light-mode page background.</td></tr><tr><td><code>light_surface</code></td><td>Hex</td><td><code>#f7f7f7</code></td><td>Light-mode base surface.</td></tr><tr><td><code>light_elevated</code></td><td>Hex</td><td><code>#ffffff</code></td><td>Light-mode raised surface.</td></tr><tr><td><code>light_ink</code></td><td>Hex</td><td><code>#181818</code></td><td>Light-mode primary text.</td></tr><tr><td><code>light_muted</code></td><td>Hex</td><td><code>#585858</code></td><td>Light-mode secondary text.</td></tr><tr><td><code>light_border</code></td><td>Hex</td><td><code>#dedede</code></td><td>Light-mode strong borders.</td></tr><tr><td><code>light_success</code></td><td>Hex</td><td><code>#1c985a</code></td><td>Light-mode success.</td></tr><tr><td><code>light_warning</code></td><td>Hex</td><td><code>#c28e24</code></td><td>Light-mode warning.</td></tr><tr><td><code>light_danger</code></td><td>Hex</td><td><code>#d73431</code></td><td>Light-mode danger.</td></tr><tr><td><code>mode_toggle</code></td><td>Switch</td><td><code>1</code></td><td>Lets users switch dark/light themselves from the account menu. Disable to enforce one mode for everyone.</td></tr><tr><td><code>sounds_default</code></td><td>Switch</td><td><code>0</code></td><td>Default state of interface sounds for users who never touched the toggle. Users can override per browser.</td></tr><tr><td><code>account_edit_email</code></td><td>Switch</td><td><code>0</code></td><td>Allow users to edit their own email on the account page. Off = view-only (matches stock behavior).</td></tr><tr><td><code>footer_text</code></td><td>string ≤120</td><td><em>(empty)</em></td><td>Replaces the stock footer line on client pages. Empty keeps the stock footer.</td></tr><tr><td><code>watermark</code></td><td>string ≤60</td><td><em>(empty)</em></td><td>Login-page watermark text. Empty hides it.</td></tr><tr><td><code>favicon_url</code></td><td>URL</td><td><em>(empty)</em></td><td>Custom favicon. Must be a full <code>http(s)</code> URL.</td></tr><tr><td><code>theme_color</code></td><td>Hex</td><td><em>(empty)</em></td><td>Browser UI theme-color (mobile address bar tint). Empty = derive from the palette.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Palettes come in pairs</p><p>Every dark token has a <code>light_*</code> twin. The hub&#39;s <strong>seed-color generator</strong> and curated presets fill both palettes at once — hand-tuning one mode without the other is the most common way to end up with a lopsided UI.</p></div><hr><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>Page background for the dashboard, and a fully independent set for the login/auth pages.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>bg_type</code></td><td><code>none</code> · <code>pattern</code> · <code>image</code></td><td><code>pattern</code></td><td>What paints behind the panel content.</td></tr><tr><td><code>bg_pattern</code></td><td>16 patterns</td><td><code>grid</code></td><td>Pure-CSS pattern: <code>grid</code>, <code>lines</code>, <code>dots</code>, <code>cross</code>, <code>waves</code>, <code>curves</code>, <code>mesh</code>, <code>diamond</code>, <code>noise</code>, <code>plus</code>, <code>hex</code>, <code>circuit</code>, <code>topo</code>, <code>diagonal</code>, <code>weave</code>, <code>brick</code>, <code>rings</code>.</td></tr><tr><td><code>bg_pattern_size</code></td><td>int 16–128</td><td><code>32</code></td><td>Pattern tile size (px).</td></tr><tr><td><code>bg_pattern_opacity</code></td><td>int 0–40</td><td><code>8</code></td><td>Pattern strength (%). Keep it low — patterns should whisper.</td></tr><tr><td><code>bg_image_url</code></td><td>URL or path</td><td><em>(empty)</em></td><td>Custom background image. Accepts a full URL, a panel-relative path, or the upload field&#39;s stored file.</td></tr><tr><td><code>bg_image_opacity</code></td><td>int 0–100</td><td><code>35</code></td><td>Image strength (%).</td></tr><tr><td><code>bg_image_blur</code></td><td>int 0–40</td><td><code>0</code></td><td>Image blur (px).</td></tr><tr><td><code>bg_dim</code></td><td>int 0–80</td><td><code>15</code></td><td>Darkening veil over the background (%) so content stays readable.</td></tr><tr><td><code>login_bg_url</code></td><td>URL or path</td><td><em>(empty)</em></td><td>Image override for auth pages only. Empty = the auth background follows <code>auth_bg_type</code>.</td></tr><tr><td><code>login_card</code></td><td><code>center</code> · <code>left</code></td><td><code>center</code></td><td>Login card alignment. <code>left</code> pairs well with a strong login image.</td></tr><tr><td><code>auth_bg_type</code></td><td><code>same</code> · <code>none</code> · <code>pattern</code> · <code>image</code></td><td><code>same</code></td><td>Auth pages get their own background pipeline, or <code>same</code> to mirror the main one.</td></tr><tr><td><code>auth_bg_pattern</code></td><td>16 patterns</td><td><code>grid</code></td><td>Auth pattern (same set as <code>bg_pattern</code>).</td></tr><tr><td><code>auth_bg_pattern_size</code></td><td>int 16–128</td><td><code>32</code></td><td>Auth pattern tile size.</td></tr><tr><td><code>auth_bg_pattern_opacity</code></td><td>int 0–40</td><td><code>8</code></td><td>Auth pattern strength.</td></tr><tr><td><code>auth_bg_image_url</code></td><td>URL or path</td><td><em>(empty)</em></td><td>Auth image.</td></tr><tr><td><code>auth_bg_image_opacity</code></td><td>int 0–100</td><td><code>35</code></td><td>Auth image strength.</td></tr><tr><td><code>auth_bg_image_blur</code></td><td>int 0–40</td><td><code>0</code></td><td>Auth image blur.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Hotlinked images break silently</p><p><code>bg_image_url</code> pointing at a host that blocks hotlinking (or needs auth) fails only in the browser — the save succeeds. Prefer the <strong>upload</strong> field: uploaded files are served from your own panel and always work.</p></div><hr><h2 id="sidebar" tabindex="-1">Sidebar <a class="header-anchor" href="#sidebar" aria-label="Permalink to &quot;Sidebar&quot;">​</a></h2><p>Navigation structure, dock, tab rows, brand block and the server block.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>sidebar_style</code></td><td><code>expanded</code> · <code>collapsed</code></td><td><code>expanded</code></td><td>Full labels or icon-only rail. Users get tooltips on the collapsed rail.</td></tr><tr><td><code>sidebar_dock</code></td><td><code>sticking</code> · <code>floating</code> · <code>floating_v2</code></td><td><code>floating</code></td><td>Edge-docked rail, floating panel, or the second floating variant with separated blocks.</td></tr><tr><td><code>sidebar_nav_style</code></td><td><code>default</code> · <code>pill</code></td><td><code>default</code></td><td>Row shape for tabs.</td></tr><tr><td><code>sidebar_tab_effect</code></td><td><code>box</code> · <code>rounded</code> · <code>pill</code> · <code>dot</code> · <code>solid</code></td><td><code>rounded</code></td><td>How the <em>active</em> tab is highlighted.</td></tr><tr><td><code>sidebar_hover_style</code></td><td><code>soft</code> · <code>active</code> · <code>minimal</code></td><td><code>soft</code></td><td>Hover treatment: a quiet tint, a preview of the active effect, or icon-brighten only.</td></tr><tr><td><code>sidebar_tab_jump</code></td><td>Switch</td><td><code>1</code></td><td>Subtle nudge animation when a tab becomes active.</td></tr><tr><td><code>sidebar_separators</code></td><td>Switch</td><td><code>1</code></td><td>Hairlines between sidebar category groups.</td></tr><tr><td><code>sidebar_categories</code></td><td>Switch</td><td><code>1</code></td><td>Show category headers (General, Server, Account…) in the rail.</td></tr><tr><td><code>icon_scale</code></td><td>int 80–120</td><td><code>100</code></td><td>Sidebar icon size (%).</td></tr><tr><td><code>sidebar_logo_url</code></td><td>URL or path</td><td><em>(empty)</em></td><td>Custom logo image. Empty = default mark.</td></tr><tr><td><code>sidebar_name</code></td><td>string ≤30</td><td><em>(empty)</em></td><td>Brand text next to the logo. Empty = the panel name.</td></tr><tr><td><code>sidebar_brand</code></td><td><code>both</code> · <code>icon</code> · <code>text</code></td><td><code>both</code></td><td>Which brand parts render.</td></tr><tr><td><code>sidebar_avatar</code></td><td><code>gravatar</code> · <code>initial</code></td><td><code>gravatar</code></td><td>User chip avatar: profile image or first-letter disc.</td></tr><tr><td><code>server_bar</code></td><td>Switch</td><td><code>1</code></td><td>Server identity block (name, address, power actions) pinned above the sidebar on server pages.</td></tr><tr><td><code>sidebar_server_actions</code></td><td>Switch</td><td><code>0</code></td><td>Add Start/Restart/Stop power buttons to the server block.</td></tr><tr><td><code>server_actions_colors</code></td><td><code>theme</code> · <code>custom</code></td><td><code>custom</code></td><td>Power button coloring: theme-quiet or explicit green/red.</td></tr><tr><td><code>server_switcher</code></td><td>Switch</td><td><code>1</code></td><td>Quick server switcher in the server block.</td></tr><tr><td><code>blur_server_address</code></td><td>Switch</td><td><code>0</code></td><td>Blur the server address until hovered — stream-safe default; users can still reveal on demand.</td></tr></tbody></table><hr><h2 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to &quot;Console&quot;">​</a></h2><p>Terminal surface, stats blocks, bandwidth graph and the layout zones editor.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>console_stats_style</code></td><td><code>original</code> · <code>custom</code> · <code>hidden</code></td><td><code>custom</code></td><td>Stock stat blocks, Glacier sparkline cards, or no stats at all.</td></tr><tr><td><code>console_stats_position</code></td><td><code>above</code> · <code>below</code> · <code>side</code></td><td><code>above</code></td><td>Legacy placement when the zones editor isn&#39;t used.</td></tr><tr><td><code>console_zones</code></td><td>JSON</td><td><em>(empty)</em></td><td>Ordered zones map <code>{&quot;above&quot;:[],&quot;side&quot;:[&quot;stats&quot;],&quot;below&quot;:[&quot;graph&quot;]}</code> from the drag-and-drop layout editor. Empty = defaults.</td></tr><tr><td><code>console_graph_mode</code></td><td><code>minimal</code> · <code>advanced</code></td><td><code>minimal</code></td><td>Bandwidth graph density.</td></tr><tr><td><code>console_input_float</code></td><td>Switch</td><td><code>1</code></td><td>Float the command input as its own pill, or dock it to the terminal.</td></tr><tr><td><code>console_show_address</code></td><td>Switch</td><td><code>0</code></td><td>Show the server address chip in the console header.</td></tr><tr><td><code>console_layout_editor</code></td><td><code>modern</code> · <code>legacy</code></td><td><code>modern</code></td><td>Zones editor UI generation.</td></tr><tr><td><code>console_bg</code></td><td>Hex</td><td><code>#131a20</code></td><td>Terminal canvas color — independent of the page palette.</td></tr><tr><td><code>console_bg_opacity</code></td><td>int 20–100</td><td><code>100</code></td><td>Terminal card opacity (%). Below 100 the page background shows through.</td></tr><tr><td><code>console_bg_blur</code></td><td>int 0–40</td><td><code>0</code></td><td>Extra backdrop blur for the terminal card (px).</td></tr><tr><td><code>stats_graphs</code></td><td>Switch</td><td><code>1</code></td><td>Master switch for the live bandwidth graph block.</td></tr><tr><td><code>stats_delta</code></td><td><code>off</code> · <code>latest</code> · <code>10s</code> · <code>1m</code> · <code>10m</code> · <code>custom</code></td><td><code>off</code></td><td>Show value deltas on stat cards over the chosen window.</td></tr><tr><td><code>stats_delta_custom</code></td><td>int 5–600</td><td><code>30</code></td><td>Custom delta window (seconds) when <code>stats_delta</code> is <code>custom</code>.</td></tr><tr><td><code>stats_graph_window</code></td><td>int 5–600</td><td><code>10</code></td><td>Graph history window (minutes).</td></tr><tr><td><code>stats_uptime_window</code></td><td>int 1–168</td><td><code>24</code></td><td>Uptime card averaging window (hours).</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Zones replace positions</p><p><code>console_zones</code> is the source of truth once you drag blocks in the layout editor — the legacy <code>console_stats_position</code> / <code>console_graph_position</code> only seed the initial map. Editing zones JSON by hand is supported (it must stay valid JSON) but the editor is the safe path.</p></div><hr><h2 id="animations" tabindex="-1">Animations <a class="header-anchor" href="#animations" aria-label="Permalink to &quot;Animations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>animations</code></td><td>Switch</td><td><code>1</code></td><td>Master motion switch. Off = instant transitions everywhere; also the <code>prefers-reduced-motion</code> fallback is always honored.</td></tr><tr><td><code>page_anim</code></td><td>Switch</td><td><code>1</code></td><td>Page/section reveal transitions.</td></tr><tr><td><code>files_anim_ms</code></td><td>int 100–600</td><td><code>250</code></td><td>File manager row animation duration (ms).</td></tr><tr><td><code>anim_console_reveal</code></td><td><code>instant</code> · <code>slow</code></td><td><code>instant</code></td><td>Terminal mount animation. <code>slow</code> adds a staged reveal on first paint.</td></tr></tbody></table><hr><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><p>File manager container and iconography.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>files_container_opacity</code></td><td>int 20–100</td><td><code>100</code></td><td>File browser card opacity (%).</td></tr><tr><td><code>files_container_blur</code></td><td>int 0–40</td><td><code>0</code></td><td>File browser backdrop blur (px).</td></tr><tr><td><code>files_row_bg</code></td><td>Hex</td><td><em>(empty)</em></td><td>Row tint override. Empty = theme surface.</td></tr><tr><td><code>files_icon_style</code></td><td><code>custom</code> · <code>legacy</code></td><td><code>custom</code></td><td>Glacier per-type icons or the stock set.</td></tr><tr><td><code>files_icon_folder_color</code></td><td>Hex</td><td><code>#e8934a</code></td><td>Folder icon color (custom set).</td></tr><tr><td><code>files_icon_archive_color</code></td><td>Hex</td><td><code>#a78bfa</code></td><td>Archive icon color (custom set).</td></tr><tr><td><code>files_icon_edit_color</code></td><td>Hex</td><td><code>#4ec5b1</code></td><td>Editable-file icon color (custom set).</td></tr></tbody></table><hr><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p>Server cards and the welcome bar on the server list.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>server_card_style</code></td><td><code>default</code> · <code>banner</code> · <code>fade</code></td><td><code>banner</code></td><td>Card art: stock row, banner strip image, or full-bleed cover with a bottom fade and a state edge bar.</td></tr><tr><td><code>server_card_layout</code></td><td><code>rows</code> · <code>grid</code></td><td><code>rows</code></td><td>One elongated card per row, or the shrink grid.</td></tr><tr><td><code>server_card_image</code></td><td>URL or path</td><td><em>(empty)</em></td><td>Global fallback cover image for cards without a matching rule.</td></tr><tr><td><code>welcome_bar</code></td><td>Switch</td><td><code>1</code></td><td>Greeting bar (user + Settings CTA) for non-admin users above the server list.</td></tr></tbody></table><hr><h2 id="topbar" tabindex="-1">Topbar <a class="header-anchor" href="#topbar" aria-label="Permalink to &quot;Topbar&quot;">​</a></h2><p>Optional top utility bar (complements, never duplicates, the sidebar).</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>topbar_enabled</code></td><td>Switch</td><td><code>1</code></td><td>Render the topbar.</td></tr><tr><td><code>topbar_sticky</code></td><td>Switch</td><td><code>1</code></td><td>Keep it pinned on scroll.</td></tr><tr><td><code>topbar_style</code></td><td><code>modern</code> · <code>clean</code></td><td><code>modern</code></td><td>Visual density.</td></tr><tr><td><code>topbar_search</code></td><td>Switch</td><td><code>1</code></td><td>Search pill in the bar; opens the same Ctrl+K palette.</td></tr><tr><td><code>topbar_clock</code></td><td>Switch</td><td><code>0</code></td><td>Live clock in the bar.</td></tr><tr><td><code>clock_time_format</code></td><td><code>12</code> · <code>24</code></td><td><code>24</code></td><td>Hour cycle.</td></tr><tr><td><code>clock_timezone</code></td><td><code>local</code> · <code>utc</code></td><td><code>local</code></td><td>Clock timezone.</td></tr><tr><td><code>clock_tz_label</code></td><td>Switch</td><td><code>1</code></td><td>Show the GMT offset label next to the time.</td></tr><tr><td><code>clock_date_format</code></td><td>6 formats + <code>off</code></td><td><code>off</code></td><td>Optional date next to the time (<code>dd/mm/yyyy</code>, <code>mm/dd/yyyy</code>, short variants).</td></tr></tbody></table><hr><h2 id="home-structured-lists" tabindex="-1">Home (structured lists) <a class="header-anchor" href="#home-structured-lists" aria-label="Permalink to &quot;Home (structured lists)&quot;">​</a></h2><p>Two JSON-backed lists edited with dedicated UI in the hub, not raw text.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>social_links</code></td><td>JSON list</td><td><code>[]</code></td><td>Footer/social icon links (icon + URL entries) rendered on the dashboard.</td></tr><tr><td><code>server_card_rules</code></td><td>JSON list</td><td><code>[]</code></td><td>Per-server card image rules — match servers (by name/egg) to cover images, falling back to <code>server_card_image</code>.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Edit these in the hub</p><p>Both are validated as JSON on save. Hand-editing the stored value with broken JSON is rejected — use the hub&#39;s list editors, which always emit valid payloads.</p></div><hr><h2 id="announcements" tabindex="-1">Announcements <a class="header-anchor" href="#announcements" aria-label="Permalink to &quot;Announcements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>announcements</code></td><td>JSON list</td><td><code>[]</code></td><td>Rich multi-entry announcements (markdown body, scheduling) shown on the dashboard.</td></tr><tr><td><code>announcement_enabled</code></td><td>Switch</td><td><code>0</code></td><td>The single dismissable banner.</td></tr><tr><td><code>announcement_type</code></td><td><code>info</code> · <code>success</code> · <code>warning</code> · <code>danger</code></td><td><code>info</code></td><td>Banner tone.</td></tr><tr><td><code>announcement_text</code></td><td>string ≤500</td><td><em>(empty)</em></td><td>Banner body.</td></tr><tr><td><code>announcement_dismissable</code></td><td>Switch</td><td><code>1</code></td><td>Users can close the banner (remembered per browser).</td></tr><tr><td><code>announce_cta_label</code></td><td>string ≤30</td><td><em>(empty)</em></td><td>Call-to-action button label.</td></tr><tr><td><code>announce_cta_url</code></td><td>URL or path</td><td><em>(empty)</em></td><td>Call-to-action target. Both CTA fields together render the button.</td></tr></tbody></table><hr><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><p>Managed in the hub&#39;s visual tab manager — see the <a href="./../../user-guide/tabs">Tabs guide</a>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>tabs</code></td><td>JSON list</td><td><em>(stock set)</em></td><td>Sidebar tabs for general/account pages: order, label, icon, visibility, redirect targets.</td></tr><tr><td><code>server_tabs</code></td><td>JSON list</td><td><em>(stock set)</em></td><td>The same, for server pages — an independent list.</td></tr></tbody></table><hr><h2 id="glass" tabindex="-1">Glass <a class="header-anchor" href="#glass" aria-label="Permalink to &quot;Glass&quot;">​</a></h2><p>Frosted-glass tuning for the two container families. Opacity below 100 % lets the page background bleed through; blur frosts it.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>sidebar_opacity</code></td><td>int 20–100</td><td><code>75</code></td><td>Sidebar background opacity (%).</td></tr><tr><td><code>sidebar_blur</code></td><td>int 0–40</td><td><code>18</code></td><td>Sidebar backdrop blur (px).</td></tr><tr><td><code>container_opacity</code></td><td>int 20–100</td><td><code>55</code></td><td>Content containers opacity (%).</td></tr><tr><td><code>container_blur</code></td><td>int 0–40</td><td><code>14</code></td><td>Content containers backdrop blur (px).</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Glass needs a background to show</p><p>Opacity/blur are invisible over the flat <code>bg</code> color — they only read as glass when <code>bg_type</code> is <code>pattern</code> or <code>image</code>. Strong blur with <code>bg_type: none</code> just dims things.</p></div><hr><h2 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;Advanced&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>shortcuts</code></td><td>Switch</td><td><code>1</code></td><td>Keyboard shortcuts (Ctrl+K search palette).</td></tr></tbody></table><p>The Advanced tab also carries the <strong>import/export as JSON</strong> and <strong>factory reset</strong> actions — these act on the whole configuration, they are not settings themselves. See the <a href="./../../user-guide/admin-hub#import--export--factory-reset">Admin Hub guide</a>.</p>',59)])])}const m=d(r,[["render",a]]);export{u as __pageData,m as default};
